  const adj = Array.from({ length: edges.length + 1 }, () => []);
  const connected = (from, to) => {         // is there already a path from -> to?
    const seen = new Set([from]);
    const stack = [from];
    while (stack.length > 0) {
      const x = stack.pop();
      if (x === to) return true;
      for (const y of adj[x]) {
        if (!seen.has(y)) {
          seen.add(y);
          stack.push(y);
        }
      }
    }
    return false;
  };
  for (const [u, v] of edges) {
    if (connected(u, v)) return [u, v];     // a second route: this edge closes the cycle
    adj[u].push(v);
    adj[v].push(u);
